UPDATE import_file
SET status = #{status}
WHERE id = #{id}

UPDATE import_file SET status = #{status}, processed_rows = #{processed},
       total_rows = CASE WHEN #{status} = 'IMPORTED' THEN #{success} + #{failed} ELSE total_rows END,
       success_rows = #{success}, failed_rows = #{failed}, error_message = #{error}
WHERE id = #{id}
